import{_ as t,o as a,c as s,a6 as o}from"./chunks/framework.DMOj2-2K.js";const h=JSON.parse('{"title":"Claude skills & AI assistants","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-assistants.md","filePath":"guide/ai-assistants.md"}'),i={name:"guide/ai-assistants.md"};function d(r,e,n,l,c,u){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="claude-skills-ai-assistants" tabindex="-1">Claude skills &amp; AI assistants <a class="header-anchor" href="#claude-skills-ai-assistants" aria-label="Permalink to &quot;Claude skills &amp; AI assistants&quot;">​</a></h1><p>Cluub is built so that every developer <strong>and every AI coding assistant</strong> writes code the same way. Each project comes with ready-made <a href="https://code.claude.com" target="_blank" rel="noreferrer">Claude Code</a> skills and a <code>CLAUDE.md</code> file of project rules, so Claude (or any assistant that reads them) follows Cluub&#39;s structure, naming, testing and review standards automatically.</p><h2 id="what-every-new-project-gets" tabindex="-1">What every new project gets <a class="header-anchor" href="#what-every-new-project-gets" aria-label="Permalink to &quot;What every new project gets&quot;">​</a></h2><p><code>cluub new</code> and <code>npm create cluub</code> add:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── CLAUDE.md               # project rules for AI assistants</span></span>
<span class="line"><span>└── .claude/skills/         # one folder per skill, each with a SKILL.md</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Skill</th><th>Use it to</th></tr></thead><tbody><tr><td><code>cluub-feature</code></td><td>Build a full-stack feature in the standard order: model, store, service, api, page, components, tests</td></tr><tr><td><code>cluub-backend</code></td><td>Apply backend standards: models, stores, clients, services, apis, validation, errors, AI keys</td></tr><tr><td><code>cluub-frontend</code></td><td>Apply frontend standards: pages own state, stateless components, layouts, loading/empty/error states, accessibility</td></tr><tr><td><code>cluub-naming</code></td><td>Name declarations, files, fields, actions, routes, tests, branches and commits consistently</td></tr><tr><td><code>cluub-tests</code></td><td>Write service, api and UI tests on top of the generated ones</td></tr><tr><td><code>cluub-code-review</code></td><td>Review a change for correctness, layers, validation, security, accessibility, naming and tests</td></tr><tr><td><code>cluub-review-pr</code></td><td>Review a GitHub pull request end to end and draft comments (never posts without approval)</td></tr><tr><td><code>cluub-fix-issue</code></td><td>Fix a bug safely: reproduce with a failing test, fix in the right layer, verify</td></tr><tr><td><code>cluub-security</code></td><td>Review secrets and AI keys, input validation, error leakage, auth gaps and HTTP exposure</td></tr><tr><td><code>cluub-accessibility</code></td><td>Check UIs against WCAG 2.2 AA: labels, alt text, headings, keyboard, contrast</td></tr><tr><td><code>cluub-debug</code></td><td>Diagnose compile errors, failing tests, server errors, blank pages, AI and network failures</td></tr></tbody></table><h2 id="using-them" tabindex="-1">Using them <a class="header-anchor" href="#using-them" aria-label="Permalink to &quot;Using them&quot;">​</a></h2><p>In <a href="https://code.claude.com" target="_blank" rel="noreferrer">Claude Code</a>, open your project folder and ask in plain English. Claude picks the matching skill:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a &quot;due date&quot; to todos and show overdue ones first</span></span>
<span class="line"><span>Review my changes before I commit</span></span>
<span class="line"><span>Review PR #12</span></span>
<span class="line"><span>Fix issue #7</span></span>
<span class="line"><span>Check the new checkout page for accessibility</span></span></code></pre></div><p>You can also name a skill directly, for example &quot;use the cluub-naming skill to check these names&quot;. Skills never push code, post on GitHub or publish anything without asking you first.</p><h2 id="customizing" tabindex="-1">Customizing <a class="header-anchor" href="#customizing" aria-label="Permalink to &quot;Customizing&quot;">​</a></h2><p>Skills are plain Markdown files: edit them to add your team&#39;s own rules (for example a ticket format or extra review items), or add new folders under <code>.claude/skills/</code>. Keep <code>CLAUDE.md</code> short; it&#39;s read at the start of every session.</p><h2 id="for-contributors-to-cluub-itself" tabindex="-1">For contributors to Cluub itself <a class="header-anchor" href="#for-contributors-to-cluub-itself" aria-label="Permalink to &quot;For contributors to Cluub itself&quot;">​</a></h2><p>The Cluub repository has its own skills in <code>.claude/skills/</code> (<code>compiler-change</code>, <code>repo-code-review</code>, <code>repo-review-pr</code>, <code>repo-fix-issue</code>, <code>release</code>, <code>docs-update</code>) and a repository <code>CLAUDE.md</code>. See <a href="/contributing">Contributing</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/team">POs, BAs, QAs &amp; AI</a>: <code>cluub explain</code> and <code>cluub make</code></li><li><a href="/guide/structure">Project structure &amp; layers</a></li><li><a href="/guide/testing">Automatic tests</a></li></ul>`,16)])])}const m=t(i,[["render",d]]);export{h as __pageData,m as default};
